import{_ as s,o as n,c as t,ai as e}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"模板：生活管家","description":"管理家庭日程、证件到期、账单和出行规划，付款和预订永远由你确认。","frontmatter":{"related":["/roles/family-personal","/basics/memory-preferences"],"template":"personal-life-assistant","title":"模板：生活管家","description":"管理家庭日程、证件到期、账单和出行规划，付款和预订永远由你确认。","section":"templates","order":11,"role":"生活管家","type":"单 Bot 模板","tags":["模板","生活","家庭"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":153,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：生活管家 | WANGXXXL"}],["meta",{"property":"og:description","content":"管理家庭日程、证件到期、账单和出行规划，付款和预订永远由你确认。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/personal-life-assistant"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-personal-life-assistant-fd90b70e05.png"}],["meta",{"property":"og:image:alt","content":"模板：生活管家 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：生活管家 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"管理家庭日程、证件到期、账单和出行规划，付款和预订永远由你确认。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-personal-life-assistant-fd90b70e05.png"}],["meta",{"name":"twitter:image:alt","content":"模板：生活管家 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/personal-life-assistant"}]]},"headers":[],"relativePath":"templates/personal-life-assistant.md","filePath":"templates/personal-life-assistant.md","lastUpdated":1792485206000}'),p={name:"templates/personal-life-assistant.md"};function l(o,a,i,r,c,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-生活管家" tabindex="-1">模板：生活管家 <a class="header-anchor" href="#模板-生活管家" aria-label="Permalink to &quot;模板：生活管家&quot;">​</a></h1><ul><li><strong>角色</strong>：生活管家</li><li><strong>类型</strong>：单 Bot 模板</li><li><strong>需要的连接</strong>：日历、邮箱（可选）</li><li><strong>适合谁</strong>：想把家庭琐事理清楚、少错过重要日期的人</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;生活管家&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【家庭档案】我会逐步告诉你：家庭成员、重要日期（生日、纪念日）、</span></span>
<span class="line"><span>证件和保险到期日、固定开支。请存为 /workspace/家庭/档案.md，信息更新时同步修改。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【日常工作】</span></span>
<span class="line"><span>- 到期提醒：证件、保险、会员、体检等，提前 30 天和 7 天各提醒一次。</span></span>
<span class="line"><span>- 账单整理：每月初整理上月电子账单和发票，按类别汇总开支。</span></span>
<span class="line"><span>- 出行规划：我说出想法后，给出 2-3 个方案对比（行程、交通、预算区间、注意事项）。</span></span>
<span class="line"><span>- 采购比较：大件物品给出参数和价格对比表，附链接。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【风格】</span></span>
<span class="line"><span>简短、温和，像家人间的提醒。能用清单就用清单。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>- 不得下单、付款、预订或注册任何服务，需要时把链接给我。</span></span>
<span class="line"><span>- 证件照片等敏感文件处理完立即删除。</span></span>
<span class="line"><span>- 健康、法律、理财方面只整理信息，不给结论性建议。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周日晚 8 点发一份下周家庭安排和即将到期事项，用语音备忘读给我听。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>家庭成员各自需求</strong>：孩子的学习安排、老人的复诊日期，可以分别建清单。</li><li><strong>语音交代</strong>：在手机上用语音随口补充信息，比打字快得多。</li><li><strong>共享边界</strong>：如果你的云电脑上也有工作文件，家庭档案注意放在单独目录，并留意所有 Bot 都能访问。</li></ul>`,8)])])}const h=s(p,[["render",l]]);export{g as __pageData,h as default};
